fn myfun1(x: &Vec<i32>) -> usize {
    assert!(!x.is_empty(), "Input vector must be non-empty");

    let mut max_index = 0;
    let mut max_value = x[0];

    for (i, &v) in x.iter().enumerate().skip(1) {
        if v > max_value {
            max_value = v;
            max_index = i;
        }
    }

    max_index
}

fn main() {
    let v1 = vec![1, 3, 2, 3, 1];
    let idx1 = myfun1(&v1);
    println!("Index of a maximum element in {:?} is {}", v1, idx1);
    // v1[idx1] is either 3 at index 1 or 3 at index 3

    let v2 = vec![-5];
    let idx2 = myfun1(&v2);
    println!("Index of a maximum element in {:?} is {}", v2, idx2);
    // v2[idx2] is -5
}